type OpenIncidentsAroundParams struct {
	FromTs time.Time
	ToTs   time.Time
}

// Whether an incident not closed occurred in [from_ts, to_ts) (an
// archived object of that time is then kept).
func (q *Queries) OpenIncidentsAround(ctx context.Context, arg OpenIncidentsAroundParams) (bool, error) {
	row := q.db.QueryRow(ctx, openIncidentsAround, arg.FromTs, arg.ToTs)
	var held bool
	err := row.Scan(&held)
	return held, err
}

const operatingUSSPs = `-- name: OperatingUSSPs :many
SELECT code, client_id, base_url, operations_started_at FROM certificates
WHERE holder = 'ussp' AND status IN ('operating', 'limited') AND operations = 'operating'
  AND issued_at <= now() AND valid_until > now() AND base_url <> ''
ORDER BY code
LIMIT $1
`

type OperatingUSSPsRow struct {
	Code                string
	ClientID            string
	BaseUrl             string
	OperationsStartedAt *time.Time
}

// The USSPs whose daily records are pulled: on the USSP list (02 F1),
// with a base URL.
func (q *Queries) OperatingUSSPs(ctx context.Context, maxRows int32) ([]OperatingUSSPsRow, error) {
	rows, err := q.db.Query(ctx, operatingUSSPs, maxRows)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []OperatingUSSPsRow{}
	for rows.Next() {
		var i OperatingUSSPsRow
		if err := rows.Scan(
			&i.Code,
			&i.ClientID,
			&i.BaseUrl,
			&i.OperationsStartedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const packsToReverify = `-- name: PacksToReverify :many
SELECT incident_id, pack_id, created_at FROM evidence_packs
WHERE (created_at, pack_id) > ($1::timestamptz, $2::text)
ORDER BY created_at, pack_id
LIMIT $3
`

type PacksToReverifyParams struct {
	AfterCreated time.Time
	AfterPack    string
	MaxRows      int32
}

type PacksToReverifyRow struct {
	IncidentID string
	PackID     string
	CreatedAt  time.Time
}

// Every evidence pack in creation order after a cursor, for the
// monthly re-verification.
func (q *Queries) PacksToReverify(ctx context.Context, arg PacksToReverifyParams) ([]PacksToReverifyRow, error) {
	rows, err := q.db.Query(ctx, packsToReverify, arg.AfterCreated, arg.AfterPack, arg.MaxRows)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []PacksToReverifyRow{}
	for rows.Next() {
		var i PacksToReverifyRow
		if err := rows.Scan(&i.IncidentID, &i.PackID, &i.CreatedAt); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const recordUSSPDayFetched = `-- name: RecordUSSPDayFetched :exec
INSERT INTO ussp_daily_records (ussp_code, day, state, sha256, size_bytes, archive_key, attempts)
VALUES ($1, $2, 'fetched', $3, $4, $5, 1)
ON CONFLICT (ussp_code, day) DO UPDATE
SET state = 'fetched', sha256 = EXCLUDED.sha256, size_bytes = EXCLUDED.size_bytes, archive_key = EXCLUDED.archive_key,
    attempts = ussp_daily_records.attempts + 1, last_error = NULL, updated_at = now()
`

type RecordUSSPDayFetchedParams struct {
	UsspCode   string
	Day        time.Time
	Sha256     *string
	SizeBytes  *int64
	ArchiveKey *string
}

func (q *Queries) RecordUSSPDayFetched(ctx context.Context, arg RecordUSSPDayFetchedParams) error {
	_, err := q.db.Exec(ctx, recordUSSPDayFetched,
		arg.UsspCode,
		arg.Day,
		arg.Sha256,
		arg.SizeBytes,
		arg.ArchiveKey,
	)
	return err
}

const recordUSSPDayMissing = `-- name: RecordUSSPDayMissing :one
INSERT INTO ussp_daily_records (ussp_code, day, state, attempts, last_error)
VALUES ($1, $2, 'missing', 1, $3)
ON CONFLICT (ussp_code, day) DO UPDATE
SET attempts = ussp_daily_records.attempts + 1, last_error = EXCLUDED.last_error, updated_at = now()
WHERE ussp_daily_records.state = 'missing'
RETURNING ussp_code, day, state, sha256, size_bytes, archive_key, attempts, last_error, alarmed, first_tried, updated_at, object_deleted_at
`

